effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _resolution acTamanhoDaTela
vec4 u_xlat0;
bvec4 u_xlatb0;
vec4 u_xlat1;
bvec2 u_xlatb1;
vec4 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec4 u_xlat6;
float u_xlat8;
bvec2 u_xlatb15;
vec2 u_xlat16;
bvec2 u_xlatb16;
float u_xlat17;
float u_xlat18;
bool u_xlatb18;
float u_xlat22;
float u_xlat23;
bool u_xlatb23;
float u_xlat24;
bool u_xlatb24;
void main()
{
    u_xlat0.xyz = vec3(_separate, _direction, _radius) * vec3(0.0500000007, 0.0174532942, 200.0);
    u_xlat1.x = sin(u_xlat0.y);
    u_xlat2.x = cos(u_xlat0.y);
    u_xlat2.x = u_xlat0.x * u_xlat2.x;
    u_xlat2.y = u_xlat0.x * u_xlat1.x;
    u_xlatb0.xyw = equal(ivec4(int(_red), int(_green), int(_red), int(_blue)), ivec4(1, 1, 0, 1)).xyw;
    u_xlat1.xy = u_xlat2.xy + acScreenNorm.xy;
    u_xlatb15.xy = lessThan(u_xlat1.xyxy, vec4(0.0, 0.0, 0.0, 0.0)).xy;
    u_xlatb16.xy = lessThan(vec4(1.0, 1.0, 1.0, 1.0), u_xlat1.xyxy).xy;
    u_xlat3.xy = fract(u_xlat1.xy);
    u_xlat3.xy = (-u_xlat3.xy) + vec2(1.0, 1.0);
    u_xlat16.x = (u_xlatb16.x) ? u_xlat3.x : u_xlat1.x;
    u_xlat16.y = (u_xlatb16.y) ? u_xlat3.y : u_xlat1.y;
    {
        vec4 hlslcc_movcTemp = u_xlat1;
        hlslcc_movcTemp.x = (u_xlatb15.x) ? (-u_xlat1.x) : u_xlat16.x;
        hlslcc_movcTemp.y = (u_xlatb15.y) ? (-u_xlat1.y) : u_xlat16.y;
        u_xlat1 = hlslcc_movcTemp;
    }
    u_xlatb15.x = _radius>=0.00499999989;
    if(u_xlatb15.x){
        u_xlat22 = float(1.0) / _resolution.x;
        u_xlat16.x = float(1.0) / u_xlat0.z;
        u_xlat3.y = 0.0;
        u_xlat4.x = float(0.0);
        u_xlat4.y = float(0.0);
        u_xlat4.z = float(0.0);
        u_xlat4.w = float(0.0);
        u_xlat23 = 0.0;
        u_xlat17 = (-u_xlat0.z);
        while(true){
            u_xlatb24 = u_xlat0.z<u_xlat17;
            if(u_xlatb24){break;}
            u_xlat3.x = u_xlat22 * u_xlat17;
            u_xlat3.xw = u_xlat1.xy + u_xlat3.xy;
            u_xlat5 = texture(inputImg, u_xlat3.xw);
            u_xlat3.x = -abs(u_xlat17) * u_xlat16.x + 1.0;
            u_xlat3.x = u_xlat3.x * 2.0 + -1.0;
            u_xlat24 = abs(u_xlat3.x) * (-u_xlat3.x);
            u_xlat3.x = u_xlat24 * 0.5 + u_xlat3.x;
            u_xlat3.x = u_xlat3.x + 0.5;
            u_xlat4 = u_xlat5 * u_xlat3.xxxx + u_xlat4;
            u_xlat23 = u_xlat23 + u_xlat3.x;
            u_xlat17 = u_xlat17 + 1.0;
        }
        u_xlat3 = u_xlat4 / vec4(u_xlat23);
    }
    if(!u_xlatb15.x){
        u_xlat3 = texture(inputImg, u_xlat1.xy);
    }
    u_xlat4 = texture(inputImg, u_xlat1.xy);
    u_xlat3 = (u_xlatb0.x) ? u_xlat3 : u_xlat4;
    u_xlatb1.xy = lessThan(acScreenNorm.xyxx, vec4(0.0, 0.0, 0.0, 0.0)).xy;
    u_xlatb16.xy = lessThan(vec4(1.0, 1.0, 1.0, 1.0), acScreenNorm.xyxy).xy;
    u_xlat4.xy = fract(acScreenNorm.xy);
    u_xlat4.xy = (-u_xlat4.xy) + vec2(1.0, 1.0);
    u_xlat16.x = (u_xlatb16.x) ? u_xlat4.x : acScreenNorm.x;
    u_xlat16.y = (u_xlatb16.y) ? u_xlat4.y : acScreenNorm.y;
    u_xlat1.x = (u_xlatb1.x) ? (-acScreenNorm.x) : u_xlat16.x;
    u_xlat1.y = (u_xlatb1.y) ? (-acScreenNorm.y) : u_xlat16.y;
    if(u_xlatb15.x){
        u_xlat0.x = float(1.0) / _resolution.x;
        u_xlat22 = float(1.0) / u_xlat0.z;
        u_xlat4.y = 0.0;
        u_xlat5.x = float(0.0);
        u_xlat5.y = float(0.0);
        u_xlat5.z = float(0.0);
        u_xlat5.w = float(0.0);
        u_xlat16.x = 0.0;
        u_xlat23 = (-u_xlat0.z);
        while(true){
            u_xlatb18 = u_xlat0.z<u_xlat23;
            if(u_xlatb18){break;}
            u_xlat4.x = u_xlat0.x * u_xlat23;
            u_xlat4.xz = u_xlat1.xy + u_xlat4.xy;
            u_xlat6 = texture(inputImg, u_xlat4.xz);
            u_xlat4.x = -abs(u_xlat23) * u_xlat22 + 1.0;
            u_xlat4.x = u_xlat4.x * 2.0 + -1.0;
            u_xlat18 = abs(u_xlat4.x) * (-u_xlat4.x);
            u_xlat4.x = u_xlat18 * 0.5 + u_xlat4.x;
            u_xlat4.x = u_xlat4.x + 0.5;
            u_xlat5 = u_xlat6 * u_xlat4.xxxx + u_xlat5;
            u_xlat16.x = u_xlat16.x + u_xlat4.x;
            u_xlat23 = u_xlat23 + 1.0;
        }
        u_xlat4 = u_xlat5 / u_xlat16.xxxx;
    }
    if(!u_xlatb15.x){
        u_xlat4 = texture(inputImg, u_xlat1.xy);
    }
    u_xlat5 = texture(inputImg, u_xlat1.xy);
    u_xlat4 = (u_xlatb0.y) ? u_xlat4 : u_xlat5;
    u_xlat0.xy = (-u_xlat2.xy) + acScreenNorm.xy;
    u_xlatb1.xy = lessThan(u_xlat0.xyxx, vec4(0.0, 0.0, 0.0, 0.0)).xy;
    u_xlatb2.xy = lessThan(vec4(1.0, 1.0, 0.0, 0.0), u_xlat0.xyxx).xy;
    u_xlat16.xy = fract(u_xlat0.xy);
    u_xlat2.zw = (-u_xlat16.xy) + vec2(1.0, 1.0);
    {
        vec4 hlslcc_movcTemp = u_xlat2;
        hlslcc_movcTemp.x = (u_xlatb2.x) ? u_xlat2.z : u_xlat0.x;
        hlslcc_movcTemp.y = (u_xlatb2.y) ? u_xlat2.w : u_xlat0.y;
        u_xlat2 = hlslcc_movcTemp;
    }
    {
        vec4 hlslcc_movcTemp = u_xlat0;
        hlslcc_movcTemp.x = (u_xlatb1.x) ? (-u_xlat0.x) : u_xlat2.x;
        hlslcc_movcTemp.y = (u_xlatb1.y) ? (-u_xlat0.y) : u_xlat2.y;
        u_xlat0 = hlslcc_movcTemp;
    }
    if(u_xlatb15.x){
        u_xlat1.x = float(1.0) / _resolution.x;
        u_xlat8 = float(1.0) / u_xlat0.z;
        u_xlat2.y = 0.0;
        u_xlat5.x = float(0.0);
        u_xlat5.y = float(0.0);
        u_xlat5.z = float(0.0);
        u_xlat5.w = float(0.0);
        u_xlat22 = 0.0;
        u_xlat16.x = (-u_xlat0.z);
        while(true){
            u_xlatb23 = u_xlat0.z<u_xlat16.x;
            if(u_xlatb23){break;}
            u_xlat2.x = u_xlat1.x * u_xlat16.x;
            u_xlat2.xw = u_xlat0.xy + u_xlat2.xy;
            u_xlat6 = texture(inputImg, u_xlat2.xw);
            u_xlat2.x = -abs(u_xlat16.x) * u_xlat8 + 1.0;
            u_xlat2.x = u_xlat2.x * 2.0 + -1.0;
            u_xlat23 = abs(u_xlat2.x) * (-u_xlat2.x);
            u_xlat2.x = u_xlat23 * 0.5 + u_xlat2.x;
            u_xlat2.x = u_xlat2.x + 0.5;
            u_xlat5 = u_xlat6 * u_xlat2.xxxx + u_xlat5;
            u_xlat22 = u_xlat22 + u_xlat2.x;
            u_xlat16.x = u_xlat16.x + 1.0;
        }
        u_xlat2 = u_xlat5 / vec4(u_xlat22);
    }
    if(!u_xlatb15.x){
        u_xlat2 = texture(inputImg, u_xlat0.xy);
    }
    u_xlat1 = texture(inputImg, u_xlat0.xy);
    u_xlat0 = (u_xlatb0.w) ? u_xlat2 : u_xlat1;
    u_xlat1.x = dot(u_xlat3.xyz, vec3(0.300000012, 0.589999974, 0.109999999));
    u_xlat1.y = dot(u_xlat4.xyz, vec3(0.300000012, 0.589999974, 0.109999999));
    u_xlat1.z = dot(u_xlat0.xyz, vec3(0.300000012, 0.589999974, 0.109999999));
    u_xlat0.x = u_xlat3.x;
    u_xlat0.y = u_xlat4.y;
    u_xlat1.xyz = (-u_xlat0.xyz) + u_xlat1.xyz;
    u_xlat1.xyz = vec3(_black_white) * u_xlat1.xyz + u_xlat0.xyz;
    u_xlat0.x = max(u_xlat3.w, u_xlat4.w);
    u_xlat1.w = max(u_xlat0.w, u_xlat0.x);
    if(int(_use_inner_mask) != 0) {
        u_xlat0 = texture(inputImg, acScreenNorm.xy);
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat1;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat0 = u_xlat0 * u_xlat5;
        u_xlat0 = u_xlat3 * u_xlat4 + u_xlat0;
        u_xlat2.x = u_xlat4.x * u_xlat0.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat0.w;
        fragColor.xyz = u_xlat0.xyz;
    } else {
        fragColor = u_xlat1;
    }
    return;
}
